class CustomHPOStrategy:
    """Adaptive TPE with Trust-Region Local Refinement (ATPE-TR).

    Novel HPO strategy combining five key algorithmic components:
    1. Per-dimension adaptive bandwidth KDE — captures anisotropic structure
       in the response surface (vs. scalar bandwidth in standard TPE)
    2. Trust-region local exploitation — Gaussian perturbation around the
       best configuration with adaptive radius shrinkage as search progresses
    3. Good-config mutation — 20% of TPE candidates are generated by
       perturbing top-performing observations, blending model-guided and
       evolutionary search
    4. Staleness-aware scheduling — tracks iterations without improvement
       and dynamically rebalances exploration vs. exploitation
    5. Center-biased warm start — first evaluations sample near the
       geometric center of log-scale params for faster early convergence
    """

    def __init__(self, seed: int = 42):
        self.seed = seed
        self.rng = np.random.RandomState(seed)
        self.gamma = 0.25          # top-25% for good KDE
        self.n_startup = 10        # random evals before model
        self.n_cand = 100          # EI candidates (vs. 24 in baseline TPE)
        self._obs = []             # (encoded_vec, score, config)
        self._total = None         # total budget
        self._best_cfg = None
        self._best_sc = -np.inf
        self._stale = 0            # iters since last improvement
        self._prev_best = -np.inf

    # ---------- encoding / decoding ----------

    def _encode(self, config, space):
        vec = []
        for p in space.params:
            val = config[p.name]
            if p.type == "categorical":
                idx = p.choices.index(val)
                vec.append(idx / max(len(p.choices) - 1, 1))
            elif p.type in ("float", "int"):
                if p.log_scale:
                    v = (np.log(max(val, p.low * 1.001)) - np.log(p.low)) / \
                        max(np.log(p.high) - np.log(p.low), 1e-12)
                else:
                    v = (val - p.low) / max(p.high - p.low, 1e-12)
                vec.append(float(np.clip(v, 0, 1)))
        return np.array(vec)

    def _decode(self, vec, space):
        config = {}
        for i, p in enumerate(space.params):
            v = float(np.clip(vec[i], 0, 1))
            if p.type == "categorical":
                idx = int(round(v * max(len(p.choices) - 1, 1)))
                idx = min(idx, len(p.choices) - 1)
                config[p.name] = p.choices[idx]
            elif p.type == "float":
                if p.log_scale:
                    config[p.name] = float(np.exp(
                        np.log(p.low) + v * (np.log(p.high) - np.log(p.low))))
                else:
                    config[p.name] = float(p.low + v * (p.high - p.low))
            elif p.type == "int":
                if p.log_scale:
                    config[p.name] = int(round(np.exp(
                        np.log(p.low) + v * (np.log(p.high) - np.log(p.low)))))
                else:
                    config[p.name] = int(round(p.low + v * (p.high - p.low)))
        return config

    # ---------- KDE utilities ----------

    def _bandwidths(self, samples, min_bw=0.05):
        """Per-dimension Scott's-rule bandwidth with 1.5× oversmoothing."""
        if len(samples) < 2:
            d = samples.shape[1] if samples.ndim > 1 else 1
            return np.full(d, 0.25)
        n, d = samples.shape
        stds = np.std(samples, axis=0) + 1e-8
        factor = n ** (-1.0 / (d + 4))
        return np.maximum(stds * factor * 1.5, min_bw)

    def _kde_logpdf(self, x, samples, bws):
        """Numerically stable Gaussian KDE log-density."""
        if len(samples) == 0:
            return -100.0
        diffs = x[None, :] - samples
        scaled = diffs / bws[None, :]
        log_k = -0.5 * np.sum(scaled ** 2, axis=1) - np.sum(np.log(bws))
        mx = np.max(log_k)
        return float(mx + np.log(np.mean(np.exp(log_k - mx))))

    # ---------- config generators ----------

    def _center_config(self, space):
        """Config near geometric center (log-space for log-scale params)."""
        config = {}
        for p in space.params:
            if p.type == "categorical":
                config[p.name] = p.choices[0]
            elif p.type in ("float", "int"):
                if p.log_scale:
                    mid = np.exp((np.log(p.low) + np.log(p.high)) / 2)
                else:
                    mid = (p.low + p.high) / 2.0
                config[p.name] = float(mid) if p.type == "float" \
                    else int(round(mid))
        return config

    def _tpe_suggest(self, space):
        """TPE acquisition with per-dim bandwidths + good-config mutation."""
        vecs = np.array([o[0] for o in self._obs])
        scores = np.array([o[1] for o in self._obs])
        n_good = max(1, int(self.gamma * len(scores)))
        idx = np.argsort(scores)
        good = vecs[idx[-n_good:]]
        bad = vecs[idx[:-n_good]] if len(idx) > n_good else good.copy()
        bw_g = self._bandwidths(good)
        bw_b = self._bandwidths(bad)

        best_ei, best_cfg = -np.inf, None
        n_mutate = self.n_cand // 5          # 20 % mutation candidates
        for i in range(self.n_cand):
            if i < n_mutate and len(good) > 0:
                g_idx = self.rng.randint(len(good))
                noise = self.rng.randn(space.dim) * 0.1
                x = np.clip(good[g_idx] + noise, 0, 1)
                cfg = space.clip(self._decode(x, space))
                x = self._encode(cfg, space)  # re-encode after clip
            else:
                cfg = space.sample_uniform(self.rng)
                x = self._encode(cfg, space)
            ei = self._kde_logpdf(x, good, bw_g) - \
                self._kde_logpdf(x, bad, bw_b)
            if ei > best_ei:
                best_ei, best_cfg = ei, cfg
        return best_cfg

    def _local_suggest(self, space, radius):
        """Trust-region perturbation of the current best config."""
        vec = self._encode(self._best_cfg, space)
        noise = self.rng.randn(space.dim) * radius
        # 30 % chance of a larger jump along one random dimension
        if self.rng.rand() < 0.3:
            d = self.rng.randint(space.dim)
            noise[d] *= 2.5
        new_vec = np.clip(vec + noise, 0, 1)
        return space.clip(self._decode(new_vec, space))

    # ---------- main entry point ----------

    def suggest(
        self,
        space: SearchSpace,
        history: List[Trial],
        budget_left: int,
    ) -> Tuple[Dict[str, Any], float]:
        if self._total is None:
            self._total = budget_left + len(history)

        # ---- bookkeeping ----
        if history:
            last = history[-1]
            vec = self._encode(last.config, space)
            self._obs.append((vec, last.score, last.config))
            if last.score > self._best_sc:
                self._best_sc = last.score
                self._best_cfg = last.config.copy()

        # staleness counter
        if self._best_sc > self._prev_best + 1e-10:
            self._stale = 0
            self._prev_best = self._best_sc
        else:
            self._stale += 1

        n = len(self._obs)
        prog = (self._total - budget_left) / max(self._total, 1)

        # ---- Phase 1: warm-start (first n_startup evals) ----
        if n < self.n_startup:
            if n == 0:
                return space.clip(self._center_config(space)), 1.0
            if n < 3:
                cfg = self._center_config(space)
                vec = self._encode(cfg, space)
                vec = np.clip(vec + self.rng.randn(space.dim) * 0.2, 0, 1)
                return space.clip(self._decode(vec, space)), 1.0
            return space.sample_uniform(self.rng), 1.0

        # ---- Phase 2+: adaptive strategy mix ----
        r = self.rng.rand()

        # local-exploitation probability grows with progress,
        # but is halved when the search is stale (stuck)
        local_prob = 0.0
        if self._best_cfg is not None:
            local_prob = min(0.45, 0.15 + 0.30 * prog)
            if self._stale > 5:
                local_prob *= 0.5

        if r < local_prob:
            # trust-region radius shrinks over time; grows if stale
            radius = 0.12 * max(0.3, 1.0 - 0.6 * prog)
            if self._stale > 3:
                radius = min(0.25, radius * 1.5)
            cfg = self._local_suggest(space, radius)
        elif r < local_prob + 0.75 * (1.0 - local_prob):
            cfg = self._tpe_suggest(space)
        else:
            cfg = space.sample_uniform(self.rng)

        return space.clip(cfg), 1.0

class CustomHPOStrategy:
    """Adaptive Surrogate-Guided HPO with Annealed Local Search (ASG-ALS).

    Novel contributions:
    1. Fidelity-aware TPE surrogate with per-dimension bandwidth KDE
    2. Hybrid candidate generation: KDE sampling + local perturbation + random
    3. Annealed local search with decaying perturbation scale
    4. Budget-adaptive fidelity scheduling with top-config promotion
    5. Score-weighted tournament selection for local search base
    """

    def __init__(self, seed: int = 42):
        self.seed = seed
        self.rng = np.random.RandomState(seed)
        self.gamma = 0.25
        self.n_startup = 8
        self.n_candidates = 64
        self.local_scale_init = 0.25
        self.local_scale_min = 0.05
        self._total_budget = None
        self._call_count = 0
        self._queue: List[Tuple] = []
        self._promoted = False

    def _encode(self, config, space):
        vec = []
        for p in space.params:
            val = config[p.name]
            if p.type == "categorical":
                idx = p.choices.index(val)
                vec.append(idx / max(len(p.choices) - 1, 1))
            elif p.type in ("float", "int"):
                if p.log_scale:
                    v = (np.log(val) - np.log(p.low)) / (np.log(p.high) - np.log(p.low))
                else:
                    v = (val - p.low) / (p.high - p.low)
                vec.append(float(np.clip(v, 0, 1)))
        return np.array(vec)

    def _decode(self, vec, space):
        config = {}
        for i, p in enumerate(space.params):
            v = float(np.clip(vec[i], 0, 1))
            if p.type == "categorical":
                idx = int(round(v * max(len(p.choices) - 1, 1)))
                idx = min(idx, len(p.choices) - 1)
                config[p.name] = p.choices[idx]
            elif p.type == "float":
                if p.log_scale:
                    config[p.name] = float(np.exp(
                        np.log(p.low) + v * (np.log(p.high) - np.log(p.low))))
                else:
                    config[p.name] = float(p.low + v * (p.high - p.low))
            elif p.type == "int":
                if p.log_scale:
                    config[p.name] = int(round(np.exp(
                        np.log(p.low) + v * (np.log(p.high) - np.log(p.low)))))
                else:
                    config[p.name] = int(round(p.low + v * (p.high - p.low)))
        return config

    def _kde_logpdf(self, x, samples, bw):
        """Per-dimension bandwidth Gaussian KDE with log-sum-exp stability."""
        diffs = x[None, :] - samples
        scaled = diffs / bw[None, :]
        log_k = -0.5 * np.sum(scaled ** 2, axis=1)
        mx = np.max(log_k)
        return float(mx + np.log(np.mean(np.exp(log_k - mx))))

    def _tpe_suggest(self, space, history):
        """TPE with per-dim bandwidth and hybrid candidate generation."""
        high_fid = [t for t in history if t.budget >= 0.5]
        data = high_fid if len(high_fid) >= self.n_startup else history
        if len(data) < 3:
            return space.sample_uniform(self.rng)
        vecs = np.array([self._encode(t.config, space) for t in data])
        scores = np.array([t.score for t in data])
        n_good = max(1, int(self.gamma * len(data)))
        si = np.argsort(scores)
        good = vecs[si[-n_good:]]
        bad = vecs[si[:-n_good]] if n_good < len(data) else good.copy()
        if len(bad) == 0:
            bad = good.copy()
        dim = space.dim
        n = len(data)
        scott = (4.0 / (n + 2)) ** (1.0 / (dim + 4))
        bw_g = np.maximum(np.std(good, axis=0) * scott, 0.05) if len(good) > 1 else np.full(dim, 0.2)
        bw_b = np.maximum(np.std(bad, axis=0) * scott, 0.05) if len(bad) > 1 else np.full(dim, 0.2)
        best_ei, best_cfg = -np.inf, None
        best_v = vecs[np.argmax(scores)]
        n_kde = self.n_candidates // 3
        n_local = 2 * self.n_candidates // 3
        for i in range(self.n_candidates):
            if i < n_kde:
                # Sample from good KDE: pick random component + noise
                idx = self.rng.randint(len(good))
                x = np.clip(good[idx] + self.rng.randn(dim) * bw_g, 0, 1)
                cfg = space.clip(self._decode(x, space))
            elif i < n_local:
                # Local perturbation around best observed
                x = np.clip(best_v + self.rng.randn(dim) * 0.15, 0, 1)
                cfg = space.clip(self._decode(x, space))
            else:
                # Random exploration
                cfg = space.sample_uniform(self.rng)
                x = self._encode(cfg, space)
            ei = self._kde_logpdf(x, good, bw_g) - self._kde_logpdf(x, bad, bw_b)
            if ei > best_ei:
                best_ei, best_cfg = ei, cfg
        return best_cfg or space.sample_uniform(self.rng)

    def _local_suggest(self, space, history, scale):
        """Annealed local search with score-weighted tournament selection."""
        if not history:
            return space.sample_uniform(self.rng)
        scored = sorted(
            [(t.score + 0.05 * t.budget, t) for t in history], reverse=True
        )
        base = scored[self.rng.randint(min(3, len(scored)))][1]
        vec = self._encode(base.config, space)
        mask = self.rng.random(len(vec)) < 0.8
        perturbed = np.clip(
            vec + mask * self.rng.randn(len(vec)) * scale, 0, 1
        )
        return space.clip(self._decode(perturbed, space))

    def suggest(
        self,
        space: SearchSpace,
        history: List[Trial],
        budget_left: int,
    ) -> Tuple[Dict[str, Any], float]:
        self._call_count += 1
        if self._total_budget is None:
            self._total_budget = budget_left
        bf = budget_left / max(self._total_budget, 1)
        # Promote top low-fidelity configs when past halfway point
        if not self._promoted and len(history) > self.n_startup and bf <= 0.5:
            self._promoted = True
            lf = sorted(
                [t for t in history if t.budget < 0.75],
                key=lambda t: t.score, reverse=True,
            )
            for t in lf[: min(3, len(lf))]:
                self._queue.append((t.config.copy(), 1.0))
        if self._queue:
            return self._queue.pop(0)
        progress = 1.0 - bf
        # Startup: random exploration with optional low-fidelity screening
        if len(history) < self.n_startup:
            return space.sample_uniform(self.rng), (
                0.5 if budget_left > 15 else 1.0
            )
        # Annealed local search scale
        ls = (
            self.local_scale_init * (1 - 0.8 * progress)
            + self.local_scale_min * 0.8 * progress
        )
        r = self.rng.random()
        if bf > 0.5:
            # Early phase: multi-fidelity exploration
            if r < 0.35:
                cfg = self._tpe_suggest(space, history)
            elif r < 0.60:
                cfg = self._local_suggest(space, history, ls)
            else:
                cfg = space.sample_uniform(self.rng)
            return cfg, 0.5
        elif bf > 0.25:
            # Mid phase: transition to full fidelity
            if r < 0.45:
                cfg = self._tpe_suggest(space, history)
            elif r < 0.75:
                cfg = self._local_suggest(space, history, ls)
            else:
                cfg = space.sample_uniform(self.rng)
            return cfg, 1.0
        else:
            # Late phase: focused exploitation at full fidelity
            if r < 0.50:
                cfg = self._local_suggest(space, history, ls * 0.7)
            elif r < 0.80:
                cfg = self._tpe_suggest(space, history)
            else:
                cfg = self._local_suggest(space, history, ls)
            return cfg, 1.0
